$(document).on("WebPlayerSeIniciaSistema",function(){var control=Ciel.MPC.WebPlayer.Utilidad.ObtenerControl("PasoUno","Categorias");if(!control||!control.DivContenedor){return;}
var rutaImagenes=Ciel.MPC.WebPlayer.RutaRecursos+"img/PasoUno/";var imagenes={"Rut":"","Aduanas":"","Cobranzas devoluciones e inconsistencias":"","Feria de servicios":"","Conferencias o capacitaciones":"","Otros - provisionales":"","default":"Categoria.svg"};control.callbackRepintarControl=function(objControl,divContenedor){$("div[nombre='Categorias']").find("div:first").prop("style","");$("div[nombre='Categorias']").find("div:first").addClass("btnCat");$("div[class='boton btnCategoria']").find("span:first").addClass("btnCatSpan");var contenedor=objControl.DivContenedor[0];if(!contenedor){console.error('No se encontro el contenedor de categorias');return;}
var botons=contenedor.querySelectorAll('.boton');if(!botons||!botons.length){return;}
var arrayBoton=Array.from(botons);arrayBoton.forEach(function(element){var content=element;if(!content){console.error('No se encontro un contenedor de elementos en el boton');return;}
var spanBoton=content.querySelector('span');if(!spanBoton){console.error('No se logro obtener el span del boton categoria');return;}
var textoCola=spanBoton.textContent;if(!textoCola){console.warn('No se encontro un texto para el boton categoria');textoCola="";}
var rutaImagen=imagenes[textoCola];if(!rutaImagen){rutaImagen=imagenes["default"];}
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagenes+rutaImagen);imgCola.classList.add('img-fluid');var divContentImg=document.createElement("div");divContentImg.append(imgCola);divContentImg.classList.add('contentImgCategoria');content.prepend(divContentImg);});};control.subscriptores.push(function(control,contenedor){var divContenedor=contenedor.DivContenedor[0];if(!divContenedor){console.error('No se encontro el contenedor de categorias.');return;}
var botones=divContenedor.querySelectorAll('.boton');if(!botones||!botones.length){console.error('No se encontraron categorias a mostrar.');return;}
botones.forEach(function(elemento){var llave=elemento.getAttribute('llave');if(!llave){return;}
var imgBoton=elemento.querySelector('.contentImgCategoria');if(!imgBoton){return;}
if(llave==control.Llave){imgBoton.classList.add('filterSVG');return;}
imgBoton.classList.remove('filterSVG');});});});